# Lesson 2, parts 4 to 6: inventory, inventory errors, trading investments. Executed after l2_a.py.
IN = ['תיאור', 'יחידות', 'ש״ח ליחידה', 'סה״כ ש״ח']
IW = [46, 16, 16, 22]

# ================================================================ part 4: inventory
opener(4, 'מלאי: FIFO, ממוצע, שווי מימוש נטו ורווח גולמי', 'שאלת החלק: מה עלות מה שנשאר, מה עלות מה שנמכר, ובכמה מציגים?',
       ['עלות המכר ורווח גולמי, בטבלה', 'תרשים זרימה: שלבי העבודה', 'FIFO וממוצע, בגיליון', 'שווי מימוש נטו: הנמוך מבין השניים'], 50)

D = INV([(100, 10), (100, 12), (200, 15)], [(250, 20)], 16, 2)
assert (D['fifo'], D['avg'], D['nrv'], D['fifo_bv'], D['avg_bv'], D['fifo_cogs0'], D['avg_cogs0']) == (2250, 1950, 2100, 2100, 1950, 2950, 3250)
_DSTORY = 'בחנות ״עדשה״ היו בתחילת השנה 100 משקפי שמש בעלות 10 ש״ח ליחידה. במהלך השנה נקנו 100 יחידות ב-12 ש״ח, ואחר כך 200 יחידות ב-15 ש״ח. נמכרו 250 יחידות ב-20 ש״ח ליחידה.'


def COGS(open_, buy, close, rev, keys=('op', 'by', 'cl', 'cg', 'sl', 'gp'), notes=None):
    """Cost of sales as the exam table: opening, purchases, less closing at carrying amount; then sales less cost of sales."""
    o, b, c, cg, s, g = keys
    n = notes or {}
    return [RW(o, ['מלאי פתיחה', C(open_, '', n.get('op', 'מה שהיה במחסן בתחילת השנה.'))]),
            RW(b, ['קניות', C(buy, '', n.get('by', 'כל מה שנקנה השנה.'))]),
            RW(c, ['בניכוי מלאי סגירה (ערך חשבונאי)', C(-close, '', n.get('cl', 'מה שנשאר, בסכום שבו הוא מוצג במאזן.'))]),
            RW(cg, ['עלות המכר', C(open_ + buy - close, f'=SUM(B#{o}#:B#{c}#)', n.get('cg', 'מה שהיה, ועוד מה שנקנה, פחות מה שנשאר: זה מה שנמכר.'))], 'bal'),
            RW(s, ['מכירות', C(rev, '', n.get('sl', 'יחידות שנמכרו כפול מחיר המכירה.'))]),
            RW(g, ['רווח גולמי', C(rev - (open_ + buy - close), f'=B#{s}#-B#{cg}#', n.get('gp', 'מכירות פחות עלות המכר.'))], 'net')]


S('s-idef', 'מלאי ועלות המכר', 'מה נמכר ומה נשאר: מלאי ועלות המכר',
  '<div class="row eq2 top">'
  + DEF('מלאי פתיחה ומלאי סגירה', 'המלאי ביום הראשון של השנה, והמלאי שנשאר ביום האחרון שלה. מלאי הסגירה של שנה הוא מלאי הפתיחה של הבאה.', 'פתיחה: 100 יחידות כפול 10 ש״ח, כלומר 1,000 ש״ח.', trm='openclose')
  + DEF('עלות המכר', 'עלות הסחורה שנמכרה בתקופה. זו הוצאה בדוח רווח והפסד.', 'נמכרו 250 משקפיים. כמה עלו? תלוי בשיטה.', trm='cogs') + '</div>'
  + RULE('עלות המכר לא מחשבים בנוסחה ארוכה. ממלאים <b>טבלה קבועה</b>: מלאי פתיחה, קניות, בניכוי מלאי סגירה.', 1), kick='חלק 4 · הגדרה והדגמה')

