            RW('s1', ['כל מלאי הפתיחה', 100, 10, C(1000, '=B#s1#*C#s1#', 'קודם יוצאות 100 היחידות הוותיקות ביותר.')]),
            RW('s2', ['כל הרכישה הראשונה', 100, 12, C(1200, '=B#s2#*C#s2#', 'אחריהן 100 היחידות של הרכישה הראשונה.')]),
            RW('s3', ['חלק מן הרכישה השנייה', C(50, '=250-B#s1#-B#s2#', 'חסרות עוד $250 - 100 - 100 = 50$ יחידות, מן הרכישה השנייה.'), 15, C(750, '=B#s3#*C#s3#', '50 כפול 15.')]),
            RW('cg', ['עלות המכר', C(250, '=SUM(B#s1#:B#s3#)', ''), '', C(2950, '=SUM(D#s1#:D#s3#)', 'סכום שלוש השכבות שנמכרו: 1,000 ועוד 1,200 ועוד 750.')], 'bal'),
